"""Ghi lại bản STARTER gốc (v0) vào artifacts/versions/v0/ — khớp đúng hash của run v0.

Chạy từ starter_v0:
    python scripts/restore_v0.py
"""
import hashlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DEST = ROOT / "artifacts" / "versions" / "v0"
EXPECTED = {"system_prompt.md": "eb1c8179815b", "tools.yaml": "5b22a2476d41"}

SYSTEM_PROMPT = 'You are a fast, proactive research assistant with access to tools.\n\nThe user is busy and hates being asked questions. Whenever something is missing or unclear, do not ask them back — just make a sensible guess and call a tool right away. If a request mentions a tweet or post but doesn\'t say whose, pick a well-known account like Sam Altman. If you only have a vague reference like "this article", assume a likely URL and read it.\n\nWhen the user wants to send, post, or publish something, just go ahead and do it so they don\'t have to wait.\n\nAlways finish the request in a single step. Pick one tool and fill in its arguments using your best judgment.\n'

TOOLS_YAML = '# starter_v0 — tool declarations (intentionally vague).\n# Names and descriptions here are a rough first draft. Routing rules, name->handle\n# mapping, arg conventions (news/timeframe/Top), and the send-confirmation boundary\n# are NOT spelled out anywhere yet. Your job is to make these declarations + the\n# system prompt good enough that the agent routes correctly on the eval.\n#\n# If you rename a tool, keep the name in sync across:\n#   this file  ->  tools/__init__.py (TOOL_FUNCTIONS)  ->  data/eval_base.json + data/eval_research_extension.json\n# `pytest tests/test_tool_contract.py` checks this sync for you.\n#\n# TODO(student):\n#   - Rewrite every description: what it does, WHEN to use it, WHEN NOT to use it.\n#   - Spell out arg conventions in parameter descriptions (handle format, topic/timeframe, search_type).\n#   - Make the `send` confirmation boundary explicit.\n#   - Declare your new tool(s) at the end of this file.\ntools:\n  # ---------------- Core tools ----------------\n  - name: clarify\n    description: "Gửi một câu hỏi cho người dùng."\n    parameters:\n      type: object\n      properties:\n        question: {type: string, default: "", description: "Câu hỏi"}\n        response_type: {type: string, enum: [text, yes_no, choice], default: "text", description: "Kiểu trả lời"}\n        options: {type: array, default: [], items: {type: string}, description: "Các lựa chọn"}\n      required: [question]\n\n  - name: timeline\n    description: "Lấy các bài đăng gần đây."\n    parameters:\n      type: object\n      properties:\n        screenname: {type: string, default: "", description: "Tên tài khoản"}\n        limit: {type: integer, default: 5, description: "Số lượng"}\n      required: [screenname]\n\n  - name: social_search\n    description: "Tìm trên mạng xã hội."\n    parameters:\n      type: object\n      properties:\n        query: {type: string, default: "", description: "Từ khóa"}\n        search_type: {type: string, enum: [Latest, Top], default: "Latest", description: "Cách sắp xếp"}\n        limit: {type: integer, default: 5, description: "Số lượng"}\n      required: [query]\n\n  - name: lookup\n    description: "Tra cứu thông tin trên internet."\n    parameters:\n      type: object\n      properties:\n        query: {type: string, default: "", description: "Truy vấn"}\n        topic: {type: string, enum: [general, news], default: "general", description: "Phân loại"}\n        timeframe: {type: string, enum: [day, week, month, year], default: "week", description: "Khoảng thời gian"}\n        max_results: {type: integer, default: 5, description: "Số kết quả"}\n      required: [query]\n\n  - name: fetch\n    description: "Lấy nội dung từ một địa chỉ."\n    parameters:\n      type: object\n      properties:\n        url: {type: string, default: "", description: "Địa chỉ"}\n      required: [url]\n\n  - name: format\n    description: "Trình bày dữ liệu đã có thành văn bản."\n    parameters:\n      type: object\n      properties:\n        items:\n          type: array\n          default: []\n          description: "Danh sách item"\n          items:\n            type: object\n            properties:\n              title: {type: string}\n              url: {type: string}\n              source: {type: string}\n              summary: {type: string}\n              section: {type: string}\n        template: {type: string, enum: [brief, sections, bullets, thread, daily_ai_vn], default: "sections", description: "Khuôn"}\n        headline: {type: string, default: "", description: "Tiêu đề"}\n      required: [items, template]\n\n  # ---------------- Bonus tools ----------------\n  - name: send\n    description: "Gửi một đoạn văn bản đi."\n    parameters:\n      type: object\n      properties:\n        text: {type: string, default: "", description: "Nội dung"}\n        confirmed: {type: boolean, default: false, description: "Cờ xác nhận"}\n      required: [text]\n\n  - name: policy\n    description: "Tìm trong tài liệu nội bộ."\n    parameters:\n      type: object\n      properties:\n        query: {type: string, default: "", description: "Truy vấn"}\n        policy_area: {type: string, enum: [all, ai_research, source_citation, data_privacy, external_publishing, tool_usage], default: "all", description: "Nhóm"}\n        top_k: {type: integer, default: 3, description: "Số mục"}\n      required: [query]\n\n  - name: papers\n    description: "Tìm bài báo khoa học."\n    parameters:\n      type: object\n      properties:\n        query: {type: string, default: "", description: "Từ khóa"}\n        max_results: {type: integer, default: 5, description: "Số lượng"}\n        sort_by: {type: string, enum: [relevance, lastUpdatedDate, submittedDate], default: "relevance", description: "Sắp xếp"}\n      required: [query]\n\n  - name: paper_text\n    description: "Lấy nội dung text của một bài báo."\n    parameters:\n      type: object\n      properties:\n        arxiv_url: {type: string, default: "", description: "ID hoặc địa chỉ"}\n        max_pages: {type: integer, default: 5, description: "Số trang"}\n        max_chars: {type: integer, default: 8000, description: "Số ký tự"}\n      required: [arxiv_url]\n'


def main() -> None:
    DEST.mkdir(parents=True, exist_ok=True)
    for name, text in (("system_prompt.md", SYSTEM_PROMPT), ("tools.yaml", TOOLS_YAML)):
        data = text.replace("\n", "\r\n").encode("utf-8")  # bản gốc dùng xuống dòng kiểu Windows (CRLF)
        (DEST / name).write_bytes(data)
        h = hashlib.sha256(data).hexdigest()[:12]
        ok = "✅ khớp run v0" if h == EXPECTED[name] else f"⚠️ hash {h} khác {EXPECTED[name]}"
        print(f"  {name:<18} {ok}")
    print(f"Đã ghi bản starter vào {DEST}")


if __name__ == "__main__":
    main()
